1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root { --cell: 28px; }
9	  * { box-sizing: border-box; }
10	  body {
11	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
12	    background: #14161c; color: #e8e8ec; font: 15px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
13	  }
14	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; flex-wrap: wrap; justify-content: center; }
15	  .board {
16	    display: grid; grid-template-columns: repeat(10, var(--cell)); grid-template-rows: repeat(20, var(--cell));
17	    gap: 1px; padding: 1px; background: #262a33; border: 2px solid #3a3f4b; border-radius: 4px;
18	  }
19	  .cell { width: var(--cell); height: var(--cell); background: #0d0f14; }
20	  .cell[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18), inset 0 -3px 0 rgba(0,0,0,0.25); }
21	  .panel { display: flex; flex-direction: column; gap: 14px; min-width: 150px; }
22	  .stat { background: #1c1f27; border: 1px solid #2c313c; border-radius: 6px; padding: 8px 12px; }
23	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: #9097a6; }
24	  .stat .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
25	  .next-list { display: flex; flex-direction: column; gap: 8px; margin-top: 6px; }
26	  .preview { display: grid; grid-template-columns: repeat(4, 20px); grid-template-rows: repeat(2, 20px); gap: 1px; }
27	  .preview .mini { width: 20px; height: 20px; background: transparent; }
28	  .preview .mini[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18); }
29	  .status { min-height: 1.4em; color: #ff8a80; font-weight: 600; }
30	  .help { font-size: 13px; color: #9097a6; }
31	  .help kbd { background: #2c313c; border-radius: 3px; padding: 0 5px; color: #e8e8ec; font: inherit; }
32	  button {
33	    background: #3a6ff7; color: #fff; border: 0; border-radius: 6px; padding: 8px 12px;
34	    font: inherit; font-weight: 600; cursor: pointer;
35	  }
36	</style>
37	</head>
38	<body>
39	<div class="game">
40	  <div class="board" data-testid="board"></div>
41	  <div class="panel">
42	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score">0</div></div>
43	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level">1</div></div>
44	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines">0</div></div>
45	    <div class="stat"><div class="label">Next</div><div class="next-list" data-testid="next-piece"></div></div>
46	    <div class="status" data-testid="status"><span data-testid="game-over" hidden></span></div>
47	    <button type="button" id="new-game">New game</button>
48	    <div class="help">
49	      <kbd>←</kbd> <kbd>→</kbd> move<br>
50	      <kbd>↑</kbd> rotate<br>
51	      <kbd>↓</kbd> soft drop<br>
52	      <kbd>Space</kbd> hard drop
53	    </div>
54	  </div>
55	</div>
56	<script>
57	(function () {
58	  'use strict';
59	
60	  var ROWS = 20, COLS = 10;
61	  var TYPES = ['I', 'O', 'T', 'S', 'Z', 'J', 'L'];
62	  var COLORS = {
63	    I: '#00bcd4', O: '#f5c400', T: '#9c27b0', S: '#43a047',
64	    Z: '#e53935', J: '#1e63d6', L: '#fb8c00'
65	  };
66	  // Spawn orientation, as [row, col] offsets from the piece origin.
67	  var SHAPES = {
68	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
69	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
70	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
71	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
72	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
73	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
74	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
75	  };
76	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
77	  var GRAVITY_MS = 1000;
78	  var PREVIEW_COUNT = 3;
79	
80	  // Clockwise rotation states. Each is a quarter turn of the one before, inside the
81	  // piece's box (2x2 for O, 3x3 for the rest). I is listed by hand so it turns about its middle.
82	  var ROTATIONS = {};
83	  TYPES.forEach(function (t) {
84	    var n = t === 'O' ? 2 : 3;
85	    var states = [SHAPES[t]];
86	    for (var k = 1; k < 4; k++) {
87	      states.push(states[k - 1].map(function (p) { return [p[1], n - 1 - p[0]]; }));
88	    }
89	    ROTATIONS[t] = states;
90	  });
91	  ROTATIONS.I = [
92	    SHAPES.I,
93	    [[0, 2], [1, 2], [2, 2], [3, 2]],
94	    [[1, 0], [1, 1], [1, 2], [1, 3]],
95	    [[0, 1], [1, 1], [2, 1], [3, 1]]
96	  ];
97	  // Sideways shifts tried, in order, when a rotated piece does not fit where it is.
98	  var KICKS = [0, -1, 1, -2, 2];
99	
100	  // Locking rule (a project decision): a gravity step that cannot move the piece down counts
101	  // one tick of lock delay; the piece locks on the LOCK_TICKS-th such tick. A successful left or
102	  // right move during the delay restarts it, and so does a soft drop on a piece that is already
103	  // resting; these share one cap of MAX_RESTARTS per piece. A soft drop that cannot move the piece
104	  // never counts a tick. Hard drop locks at once.
105	  var LOCK_TICKS = 2;
106	  var MAX_RESTARTS = 3;
107	
108	  // Scoring rule (a project decision): a clear scores LINE_POINTS[rows cleared at once] times the
109	  // current level. Clearing rows together must always beat clearing the same rows in smaller
110	  // groups, so every entry must exceed any sum of smaller entries that adds up to the same rows.
111	  // Soft drop scores 1 per cell moved down by the player; hard drop scores 2 per cell dropped.
112	  var LINE_POINTS = [0, 100, 300, 500, 800];
113	  var SOFT_DROP_POINTS = 1;
114	  var HARD_DROP_POINTS = 2;
115	
116	  // Game state. `board` holds the locked cells: a piece letter, or '' when empty.
117	  var board, current, queue, bag, score, level, lines, status, timer = null;
118	
119	  // ---- DOM ----
120	  var boardEl = document.querySelector('[data-testid="board"]');
121	  var scoreEl = document.querySelector('[data-testid="score"]');
122	  var levelEl = document.querySelector('[data-testid="level"]');
123	  var linesEl = document.querySelector('[data-testid="lines"]');
124	  var nextEl = document.querySelector('[data-testid="next-piece"]');
125	  var gameOverEl = document.querySelector('[data-testid="game-over"]');
126	  var cellEls = [];
127	  var itemEls = [];
128	  var miniEls = [];
129	
130	  for (var r = 0; r < ROWS; r++) {
131	    cellEls.push([]);
132	    for (var c = 0; c < COLS; c++) {
133	      var el = document.createElement('div');
134	      el.className = 'cell';
135	      el.setAttribute('data-testid', 'cell');
136	      el.setAttribute('data-row', String(r));
137	      el.setAttribute('data-col', String(c));
138	      boardEl.appendChild(el);
139	      cellEls[r].push(el);
140	    }
141	  }
142	  // One 4x2 mini grid per upcoming piece. The first grid keeps the older data-testid="next".
143	  for (var i = 0; i < PREVIEW_COUNT; i++) {
144	    var item = document.createElement('div');
145	    item.className = 'preview';
146	    item.setAttribute('data-testid', 'next-piece-item');
147	    nextEl.appendChild(item);
148	    itemEls.push(item);
149	    var grid = item;
150	    if (i === 0) {
151	      grid = document.createElement('div');
152	      grid.className = 'preview';
153	      grid.setAttribute('data-testid', 'next');
154	      item.className = '';
155	      item.appendChild(grid);
156	    }
157	    miniEls.push([]);
158	    for (var mr = 0; mr < 2; mr++) {
159	      miniEls[i].push([]);
160	      for (var mc = 0; mc < 4; mc++) {
161	        var m = document.createElement('div');
162	        m.className = 'mini';
163	        grid.appendChild(m);
164	        miniEls[i][mr].push(m);
165	      }
166	    }
167	  }
168	
169	  function paint(el, type) {
170	    el.setAttribute('data-filled', type ? 'true' : 'false');
171	    el.setAttribute('data-piece', type || '');
172	    el.style.backgroundColor = type ? COLORS[type] : '';
173	  }
174	
175	  function render() {
176	    var view = board.map(function (row) { return row.slice(); });
177	    if (current) {
178	      pieceCells(current).forEach(function (p) { view[p[0]][p[1]] = current.type; });
179	    }
180	    for (var r = 0; r < ROWS; r++) {
181	      for (var c = 0; c < COLS; c++) paint(cellEls[r][c], view[r][c]);
182	    }
183	
184	    for (var i = 0; i < PREVIEW_COUNT; i++) {
185	      var upcoming = queue[i] || '';
186	      itemEls[i].setAttribute('data-piece', upcoming);
187	      for (var mr = 0; mr < 2; mr++) {
188	        for (var mc = 0; mc < 4; mc++) paint(miniEls[i][mr][mc], '');
189	      }
190	      if (upcoming) {
191	        SHAPES[upcoming].forEach(function (p) { paint(miniEls[i][p[0]][p[1]], upcoming); });
192	      }
193	    }
194	
195	    scoreEl.textContent = String(score);
196	    levelEl.textContent = String(level);
197	    linesEl.textContent = String(lines);
198	    var over = status === 'gameover';
199	    gameOverEl.hidden = !over;
200	    gameOverEl.textContent = over ? 'Game over' : '';
201	  }
202	
203	  // ---- Pieces ----
204	  function randomPiece() {
205	    if (!bag.length) {
206	      bag = TYPES.slice();
207	      for (var i = bag.length - 1; i > 0; i--) {
208	        var j = Math.floor(Math.random() * (i + 1));
209	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
210	      }
211	    }
212	    return bag.pop();
213	  }
214	
215	  // Keep at least PREVIEW_COUNT pieces waiting, so the preview is always full.
216	  function fillQueue() {
217	    while (queue.length < PREVIEW_COUNT) queue.push(randomPiece());
218	  }
219	
220	  function takeNext() {
221	    fillQueue();
222	    var type = queue.shift();
223	    fillQueue();
224	    return type;
225	  }
226	
227	  function pieceCells(piece) {
228	    return ROTATIONS[piece.type][piece.rot].map(function (p) { return [piece.row + p[0], piece.col + p[1]]; });
229	  }
230	
231	  function fits(cells) {
232	    return cells.every(function (p) {
233	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && !board[p[0]][p[1]];
234	    });
235	  }
236	
237	  function spawn() {
238	    var type = takeNext();
239	    var piece = { type: type, row: 0, col: SPAWN_COL[type], rot: 0, lockTicks: 0, restarts: 0 };
240	    if (!fits(pieceCells(piece))) {
241	      current = null;
242	      status = 'gameover';
243	      stopTimer();
244	      return;
245	    }
246	    current = piece;
247	  }
248	
249	  function move(dr, dc) {
250	    if (!current) return false;
251	    var moved = { type: current.type, row: current.row + dr, col: current.col + dc, rot: current.rot };
252	    if (!fits(pieceCells(moved))) return false;
253	    current.row = moved.row;
254	    current.col = moved.col;
255	    return true;
256	  }
257	
258	  // Left or right. During the lock delay, a successful move restarts it, up to the cap.
259	  function shift(dc) {
260	    if (move(0, dc)) restartLock();
261	  }
262	
263	  // Down, one row. On a piece already resting it counts no lock tick and restarts the delay like a
264	  // sideways move, sharing the same cap.
265	  function softDrop() {
266	    if (move(1, 0)) {
267	      current.lockTicks = 0;
268	      score += SOFT_DROP_POINTS;
269	    } else {
270	      restartLock();
271	    }
272	  }
273	
274	  function restartLock() {
275	    if (current.lockTicks > 0 && current.restarts < MAX_RESTARTS) {
276	      current.lockTicks = 0;
277	      current.restarts++;
278	    }
279	  }
280	
281	  // Try the next clockwise state in place, then shifted sideways. If nothing fits, change nothing.
282	  function rotateCW() {
283	    if (!current) return false;
284	    var rot = (current.rot + 1) % 4;
285	    for (var i = 0; i < KICKS.length; i++) {
286	      var turned = { type: current.type, row: current.row, col: current.col + KICKS[i], rot: rot };
287	      if (fits(pieceCells(turned))) {
288	        current.col = turned.col;
289	        current.rot = rot;
290	        return true;
291	      }
292	    }
293	    return false;
294	  }
295	
296	  // Remove every full row; the rows above drop down. Returns how many rows went.
297	  function clearLines() {
298	    var kept = board.filter(function (row) { return !row.every(Boolean); });
299	    var cleared = ROWS - kept.length;
300	    for (var i = 0; i < cleared; i++) kept.unshift(new Array(COLS).fill(''));
301	    board = kept;
302	    return cleared;
303	  }
304	
305	  function lock() {
306	    pieceCells(current).forEach(function (p) { board[p[0]][p[1]] = current.type; });
307	    current = null;
308	    var cleared = clearLines();
309	    lines += cleared;
310	    score += LINE_POINTS[cleared] * level;
311	    spawn();
312	  }
313	
314	  // One gravity step. The real timer and tick() both run exactly this. Returns true if the piece moved down.
315	  function gravityStep() {
316	    if (status !== 'running' || !current) return false;
317	    if (move(1, 0)) {
318	      current.lockTicks = 0;
319	      return true;
320	    }
321	    current.lockTicks++;
322	    if (current.lockTicks >= LOCK_TICKS) lock();
323	    return false;
324	  }
325	
326	  function gravity() {
327	    gravityStep();
328	    render();
329	  }
330	
331	  function stopTimer() {
332	    if (timer !== null) { clearInterval(timer); timer = null; }
333	  }
334	
335	  function startTimer() {
336	    stopTimer();
337	    timer = setInterval(gravity, GRAVITY_MS);
338	  }
339	
340	  // ---- Actions ----
341	  function input(action) {
342	    if (status !== 'running' || !current) return;
343	    if (action === 'left') shift(-1);
344	    else if (action === 'right') shift(1);
345	    else if (action === 'rotateCW') rotateCW();
346	    else if (action === 'softDrop') softDrop();
347	    else if (action === 'hardDrop') {
348	      while (move(1, 0)) score += HARD_DROP_POINTS;
349	      lock();
350	    }
351	    render();
352	  }
353	
354	  function toQueue(list) {
355	    return (Array.isArray(list) ? list : [])
356	      .map(function (t) { return String(t).toUpperCase(); })
357	      .filter(function (t) { return SHAPES.hasOwnProperty(t); });
358	  }
359	
360	  function newGame(list) {
361	    board = [];
362	    for (var r = 0; r < ROWS; r++) board.push(new Array(COLS).fill(''));
363	    bag = [];
364	    queue = toQueue(list);
365	    score = 0;
366	    level = 1;
367	    lines = 0;
368	    status = 'running';
369	    current = null;
370	    spawn();
371	    if (status === 'running') startTimer();
372	    render();
373	  }
374	
375	  function setQueue(list) {
376	    queue = toQueue(list);
377	    fillQueue();
378	    render();
379	  }
380	
381	  function setBoard(rows) {
382	    for (var r = 0; r < ROWS; r++) {
383	      var line = rows && typeof rows[r] === 'string' ? rows[r] : '';
384	      for (var c = 0; c < COLS; c++) {
385	        var ch = line.charAt(c).toUpperCase();
386	        board[r][c] = SHAPES.hasOwnProperty(ch) ? ch : '';
387	      }
388	    }
389	    render();
390	  }
391	
392	  function getBoard() {
393	    return board.map(function (row) {
394	      return row.map(function (t) { return t || '.'; }).join('');
395	    });
396	  }
397	
398	  function getState() {
399	    return {
400	      current: current ? { type: current.type, cells: pieceCells(current) } : null,
401	      next: queue.slice(),
402	      score: score,
403	      level: level,
404	      lines: lines,
405	      status: status
406	    };
407	  }
408	
409	  function tick(n) {
410	    var steps = n === undefined ? 1 : n;
411	    for (var i = 0; i < steps; i++) gravity();
412	  }
413	
414	  window.__tetris = {
415	    newGame: newGame,
416	    setQueue: setQueue,
417	    setBoard: setBoard,
418	    tick: tick,
419	    input: input,
420	    getBoard: getBoard,
421	    getState: getState
422	  };
423	
424	  var KEYS = { ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'rotateCW', ArrowDown: 'softDrop', ' ': 'hardDrop', Spacebar: 'hardDrop' };
425	  document.addEventListener('keydown', function (e) {
426	    var action = KEYS[e.key];
427	    if (!action) return;
428	    e.preventDefault();
429	    input(action);
430	  });
431	  document.getElementById('new-game').addEventListener('click', function (e) {
432	    e.currentTarget.blur();
433	    newGame();
434	  });
435	
436	  newGame();
437	})();
438	</script>
439	</body>
440	</html>
